```python name=a2a_mcp_hitl/core/a2a_server.py
"""
Base A2A Server with HITL support.
"""
import json
import asyncio
import uuid
from abc              import ABC, abstractmethod
from typing           import AsyncGenerator, Optional
from fastapi          import FastAPI, Request
from fastapi.responses import JSONResponse
from fastapi.middleware.cors import CORSMiddleware
from sse_starlette.sse import EventSourceResponse

from core.models import (
    AgentCard, Task, TaskStatus, TaskState,
    A2ARequest, A2AResponse, Message, Artifact,
)

class BaseA2AServer(ABC):
    """Base A2A server every agent inherits from."""

    def __init__(self, card: AgentCard):
        self.card  = card
        self.tasks: dict[str, Task] = {}
        self.app   = self._build_app()

    def _build_app(self) -> FastAPI:
        app = FastAPI(title=self.card.name)
        app.add_middleware(CORSMiddleware,
                           allow_origins=["*"],
                           allow_methods=["*"],
                           allow_headers=["*"])

        @app.get("/.well-known/agent.json")
        async def agent_card():
            return self.card.model_dump()

        @app.get("/health")
        async def health():
            return {"status": "ok", "agent": self.card.name}

        @app.post("/a2a")
        async def handle(request: Request):
            body = await request.json()
            return await self._dispatch(body)

        @app.get("/a2a/stream/{task_id}")
        async def stream(task_id: str):
            return EventSourceResponse(self._sse_stream(task_id))

        return app

    async def _dispatch(self, body: dict) -> JSONResponse:
        req = A2ARequest(**body)
        try:
            if req.method == "tasks/send":
                params = req.params
                task_id = params.get("id") or str(uuid.uuid4())
                msg_data = params.get("message", {})

                parts_raw = msg_data.get("parts", [])
                from core.models import TextPart, Role
                parts = [TextPart(text=p.get("text",""))
                         for p in parts_raw if p.get("type") == "text"]
                message   = Message(role=Role.USER, parts=parts or [TextPart(text="")])

                task = Task(
                    id       = task_id,
                    status   = TaskStatus(state=TaskState.SUBMITTED),
                    messages = [message],
                    metadata = params.get("metadata", {}),
                )
                self.tasks[task_id] = task
                asyncio.create_task(self._process_and_update(task))
                return JSONResponse(A2AResponse(id=req.id, result=task.model_dump()).model_dump())

            elif req.method == "tasks/get":
                task_id = req.params.get("id","")
                task    = self.tasks.get(task_id)
                if not task:
                    return JSONResponse(A2AResponse(id=req.id,
                        error={"code": 404, "message": "Task not found"}).model_dump())
                return JSONResponse(A2AResponse(id=req.id, result=task.model_dump()).model_dump())

            elif req.method == "tasks/sendSubscribe":
                result     = (await self._dispatch({**body, "method": "tasks/send"})).body
                import json as _json
                data       = _json.loads(result)
                task_id    = data["result"]["id"]
                stream_url = f"{self.card.url}/a2a/stream/{task_id}"
                data["result"]["stream_url"] = stream_url
                return JSONResponse(data)

            else:
                return JSONResponse(A2AResponse(id=req.id,
                    error={"code": -32601, "message": f"Unknown method: {req.method}"}).model_dump())

        except Exception as e:
            return JSONResponse(A2AResponse(id=req.id,
                error={"code": -32603, "message": str(e)}).model_dump())

    async def _process_and_update(self, task: Task):
        task.status = TaskStatus(state=TaskState.WORKING)
        try:
            async for update in self.process_task(task):
                if isinstance(update, Artifact):
                    task.artifacts.append(update)
                elif isinstance(update, Message):
                    task.messages.append(update)
                elif isinstance(update, TaskStatus):
                    task.status = update
            if task.status.state == TaskState.WORKING:
                task.status = TaskStatus(state=TaskState.COMPLETED)
        except Exception as e:
            task.status = TaskStatus(state=TaskState.FAILED,
                                     message=Message.agent(f"Error: {e}"))

    async def _sse_stream(self, task_id: str) -> AsyncGenerator:
        task = self.tasks.get(task_id)
        if not task:
            yield {"event": "error", "data": json.dumps({"error": "Not found"})}
            return

        last = 0
        while task.status.state in [TaskState.SUBMITTED,
                                      TaskState.WORKING,
                                      TaskState.AWAITING_HUMAN]:
            await asyncio.sleep(0.2)
            if len(task.artifacts) > last:
                for art in task.artifacts[last:]:
                    yield {"event": "artifact",
                           "data":  json.dumps(art.model_dump())}
                last = len(task.artifacts)

        yield {"event": "complete", "data": json.dumps(task.model_dump())}

    @abstractmethod
    async def process_task(self, task: Task) -> AsyncGenerator:
        ...

    def run(self, port: int = 8001):
        import uvicorn
        uvicorn.run(self.app, host="0.0.0.0", port=port, log_level="warning")
