```python name=a2a_mcp_hitl/core/a2a_client.py
"""A2A Client — connects to any A2A agent."""
import json
import asyncio
import httpx
from typing   import Optional, AsyncGenerator
from core.models import AgentCard, Task, TaskState, A2ARequest, Message

class A2AClient:
    def __init__(self, url: str, timeout: float = 120.0):
        self.url     = url.rstrip("/")
        self.timeout = timeout
        self._http   = httpx.AsyncClient(timeout=self.timeout)

    async def discover(self) -> AgentCard:
        r    = await self._http.get(f"{self.url}/.well-known/agent.json")
        r.raise_for_status()
        return AgentCard(**r.json())

    async def send_task(self, message: str, session_id: str = None) -> Task:
        req  = A2ARequest(
            method = "tasks/send",
            params = {
                "message":    Message.user(message).model_dump(),
                "session_id": session_id,
            }
        )
        resp = await self._http.post(f"{self.url}/a2a", json=req.model_dump())
        resp.raise_for_status()
        data    = resp.json()
        task_id = data["result"]["id"]
        return await self._poll(task_id)

    async def _poll(self, task_id: str, interval: float = 0.5, max_wait: float = 180.0) -> Task:
        elapsed = 0.0
        while elapsed < max_wait:
            req  = A2ARequest(method="tasks/get", params={"id": task_id})
            resp = await self._http.post(f"{self.url}/a2a", json=req.model_dump())
            task = Task(**resp.json()["result"])
            if task.status.state in [TaskState.COMPLETED, TaskState.FAILED, TaskState.CANCELLED]:
                return task
            if task.status.state == TaskState.AWAITING_HUMAN:
                print(f"    ⏸️  Task {task_id} awaiting human input...")
            await asyncio.sleep(interval)
            elapsed += interval
        raise TimeoutError(f"Task {task_id} timed out")

    async def stream_task(self, message: str) -> AsyncGenerator[dict, None]:
        req  = A2ARequest(method="tasks/sendSubscribe",
                          params={"message": Message.user(message).model_dump()})
        resp = await self._http.post(f"{self.url}/a2a", json=req.model_dump())
        data = resp.json()["result"]
        stream_url = data.get("stream_url", f"{self.url}/a2a/stream/{data['id']}")
        async with self._http.stream("GET", stream_url) as s:
            async for line in s.aiter_lines():
                if line.startswith("data:"):
                    raw = line[5:].strip()
                    if raw:
                        yield json.loads(raw)

    async def close(self): await self._http.aclose()
    async def __aenter__(self): return self
    async def __aexit__(self, *a): await self.close()
